/**
 * HAZIRLAYAN kutusuna basılacak kaşeyi ada göre bulur.
 * Kaşesi tanımlı olmayan bir TMGD için undefined döner — o durumda kutu
 * yalnızca isim/unvan ile basılır, hatalı bir kaşe basılmaz.
 */
export function hazirlayanKasesi(ad: string): GomuluKase | undefined {
  const sade = ad
    .toLocaleUpperCase("tr")
    .replace(/[^A-ZÇĞİÖŞÜ]/g, "");
  if (sade.includes("UMUTKILIN")) return KASE_UMUT_KILINC;
  return undefined;
}
